CREATE DATABASE IF NOT EXISTS OHKDB; USE OHKDB; CREATE TABLE Users ( UserID INT PRIMARY KEY AUTO_INCREMENT, Name VARCHAR(100) NOT NULL, Email VARCHAR(100) UNIQUE NOT NULL, Password VARCHAR(255) NOT NULL, Role VARCHAR(20) NOT NULL DEFAULT 'user' ); CREATE TABLE TRANSACTIONS ( TransID INT PRIMARY KEY AUTO_INCREMENT, UserID INT NOT NULL, Type VARCHAR(250) NOT NULL DEFAULT 'expenses', Amount DOUBLE NOT NULL, Category VARCHAR(250) NOT NULL DEFAULT 'Salary', TransactionDate DATE NOT NULL, Description VARCHAR(500) NULL, FOREIGN KEY (UserID) REFERENCES Users(UserID) ON DELETE RESTRICT ); INSERT INTO Users VALUES (1, 'Kaltoum Chetima', 'maimoussack@cwu.edu','1234', 'admin');
